ExposedMembers.JAC_RP_PressureProbe=function()
 local cr=Players[0]:GetCities():GetCapitalCity():GetReligion(); local out={};
 for _,r in pairs(cr:GetReligionsInCity()) do local row={}; for k,v in pairs(r) do row[#row+1]=tostring(k)..'='..tostring(v) end; table.sort(row); out[#out+1]=table.concat(row,',') end;
 table.sort(out); return table.concat(out,';')
end; return 'UI pressure reader installed'
